        "宋元素髹以轻薄坚硬的胎体、微妙的曲线和尖锐的棱线著称。葵瓣、菱花形的盘盒，口沿外撇并镶金属边，与同期定窑、汝窑瓷器的造型互为呼应，可见宋人尚简的审美。"
