          "name": "《髹饰录》蒹葭堂本",
          "dynasty": "明—江户",
          "artist": "东京国立博物馆藏",
          "version": "",
          "material": "纸本",
          "intro": [
            "《髹饰录》是明代隆庆年间安徽新安平沙漆工黄成（号大成）编撰的漆器工艺专著，天启五年（1625）由浙江西塘漆工杨明补注并作序。全书分乾、坤两集，共18章186条。",
            "此本为江户时代抄本，因源自大阪本草家木村蒹葭堂（1736—1802）旧藏而得名。1802年入藏昌平坂学问所，1881年转藏东京国立博物馆。"
          ],
